=== test-offline-list-sync.mjs ===
// gcec local check: package.json's hand-kept test:offline list must stay in sync
// with the extension-test/ mirror tree — it names every extension-test/**/*.test.js
// that exists, and only files that exist. `npm test` discovers by glob, so a test
// missing from test:offline still runs there; what this check catches is the
// offline suite silently thinning as tests are added, moved, or renamed (the rule
// this converts was prose in the project's old testing procedure doc).
//
// Local-pack check modules are dependency-free on purpose: they return plain
// finding objects ({ rule, severity, file, line, what, why, fix, doc }) instead of
// importing the engine's checks/lib helpers — the mount those helpers live in is
// gitignored and absent on a fresh checkout, and this module must also load under
// the repo's own `npm test` (pack.test.mjs).
const id = 'test-offline-list-sync';
const severity = 'blocking';
const doc = '.claudinite/local/packs/gcec/RULES.md';
const why =
  'npm test discovers by glob but test:offline is a hand-kept list — a new or ' +
  'moved extension-test file silently drops out of the offline suite';

const isMirrorTest = (p) => p.startsWith('extension-test/') && p.endsWith('.test.js');

export default {
  id,
  severity,
  description: 'package.json test:offline lists exactly the extension-test unit tests',
  doc,
  why,

  run(ctx) {
    const raw = ctx.read('package.json');
    if (!raw) return [];
    let script;
    try {
      script = JSON.parse(raw).scripts?.['test:offline'];
    } catch {
      return []; // malformed package.json breaks npm first — not this check's finding
    }
    if (typeof script !== 'string') return [];

    const listed = script.split(/\s+/).filter(isMirrorTest);
    const findings = [];
    // Direction 1 — a mirror-tree test the list is missing. ctx.files is the whole
    // repo under the engine's default `all` sweep (check-the-world); under a
    // --changed run it narrows to changed files, which only ever under-reports.
    for (const file of ctx.files.filter(isMirrorTest)) {
      if (!listed.includes(file)) {
        findings.push({
          rule: id, severity, file: 'package.json', line: null,
          what: `test:offline is missing ${file}`,
          why,
          fix: `add ${file} to the test:offline list in package.json`,
          doc,
        });
      }
    }
    // Direction 2 — a listed file that doesn't exist (moved/renamed away). Probed
    // via ctx.exists, not ctx.files, so a --changed run can't false-positive.
    for (const file of listed) {
      if (!ctx.exists(file)) {
        findings.push({
          rule: id, severity, file: 'package.json', line: null,
          what: `test:offline lists ${file}, which does not exist`,
          why,
          fix: `remove ${file} from the test:offline list or fix its path`,
          doc,
        });
      }
    }
    return findings;
  },
};
=== custom-sources-flat.mjs ===
// gcec local check: extension/event-extractors/custom/ holds per-site sources and
// nothing else — one flat `<site>.js` per site, no subdirectories, no other file
// kinds, and never a pipeline file (the registry, the orchestrator, the shared
// helpers, or the one core generic extractor, which is a different kind of thing
// from a per-site source). The architecture rule this converts is in RULES.md's
// "Architecture rules of the road": custom/ is THE extensibility point, which is
// what keeps adding a host a single-file change.
//
// Why a check and not just prose: the load-order generator (dev/build/gen-load-order.js)
// reads custom/ with `readdirSync(...).filter(f => f.endsWith('.js'))` — one level,
// name-filtered. A nested directory or a non-.js file is therefore SILENTLY dropped
// from load-order.generated.json: no error anywhere, the code simply never loads and
// the site quietly stops extracting. That silence is exactly what a static scan is for.
//
// Local-pack check modules are dependency-free on purpose (see
// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
// so they also load under the repo's own `npm test` (pack.test.mjs).
const id = 'custom-sources-flat';
const severity = 'blocking';
const doc = '.claudinite/local/packs/gcec/RULES.md';
const why =
  'gen-load-order.js reads custom/ one level deep and keeps only *.js — anything else ' +
  'is silently omitted from the load order and never runs';

const DIR = 'extension/event-extractors/custom/';

// The pipeline itself: these live in event-extractors/, never in custom/.
const PIPELINE_FILES = ['registry.js', 'generic-extractor.js', 'assemble-events.js'];

export default {
  id,
  severity,
  description: 'extension/event-extractors/custom/ holds only flat per-site <site>.js sources',
  doc,
  why,

  run(ctx) {
    const findings = [];
    // ctx.files is the whole repo under the default `all` sweep; a --changed run
    // narrows it, which only ever under-reports.
    for (const file of ctx.files) {
      if (!file.startsWith(DIR)) continue;
      const rest = file.slice(DIR.length);

      if (rest.includes('/')) {
        findings.push({
          rule: id, severity, file, line: null,
          what: `${file} sits in a subdirectory of custom/`,
          why,
          fix: 'flatten it to extension/event-extractors/custom/<site>.js, or move shared code to event-extractors/helpers/',
          doc,
        });
        continue;
      }

      if (!rest.endsWith('.js')) {
        findings.push({
          rule: id, severity, file, line: null,
          what: `${file} is not a per-site source (custom/ holds only <site>.js files)`,
          why,
          fix: 'move it out of custom/ — that directory is the per-site extensibility point and nothing else',
          doc,
        });
        continue;
      }

      if (PIPELINE_FILES.includes(rest)) {
        findings.push({
          rule: id, severity, file, line: null,
          what: `${file} is a pipeline file, not a per-site source`,
          why: 'the registry, the orchestrator and the core generic extractor are the pipeline itself — a different kind of thing from a per-site override',
          fix: `move ${rest} back to extension/event-extractors/`,
          doc,
        });
      }
    }
    return findings;
  },
};
=== npm-test-glob-coverage.mjs ===
// gcec local check: `npm test` runs everything. Its `test` script is a single
// `node --test` invocation over a hand-kept list of glob patterns — one per test
// directory — so every committed *.test.{js,mjs,cjs} in the repo must be reached
// by one of them. The rule this converts is RULES.md's first testing invariant
// ("`npm test` runs everything ... `test:e2e` (heavy, CI-only)").
//
// Why a check and not just prose: the failure is silent in exactly the way a
// static scan is for. A test file in a directory no pattern reaches is simply
// never run — `node --test` doesn't error on a glob that matches nothing, npm
// exits 0, CI stays green, and the coverage is just gone with nothing red to say
// so. The pattern list has grown one entry at a time (extension-test/,
// dev/build/test/, dev/build/release/, four separate dev/requirements/ subtrees,
// the local pack's tasks, the pack's own .mjs fixtures); the next new test
// directory is one forgotten glob away from that silence.
//
// The one carve-out is READ FROM package.json, never hardcoded: the heavy,
// CI-only e2e suite is deliberately outside `npm test`, and it declares itself
// in `scripts["test:e2e"]`. A file matched by that script's patterns is covered
// by design, so the carve-out follows the e2e suite around instead of pinning a
// path here.
//
// ONE DIRECTION ONLY, on purpose (the same choice as
// extension-test/integration/supported-domains.test.js): a *stale* pattern — one
// matching nothing — is not asserted, because a literal path that no longer
// exists makes `node --test` fail loudly on the next run. Only the silent
// direction needs a guard.
//
// Local-pack check modules are dependency-free on purpose (see
// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
// so they also load under the repo's own `npm test` (pack.test.mjs). The engine
// already drops the vendored `.claudinite/shared/` canon from ctx.files, so the
// canon's own tests are structurally out of scope and need no exemption here.
const id = 'npm-test-glob-coverage';
const severity = 'blocking';
const doc = '.claudinite/local/packs/gcec/RULES.md';
const why =
  'node --test never errors on a glob that matches nothing — a test file no pattern ' +
  'reaches silently never runs, and npm test still exits 0';

const isTestFile = (p) => /\.test\.(js|mjs|cjs)$/.test(p);

// The file/glob arguments of a `node --test …` script line. Quotes come off (the
// globs are quoted so the shell can't expand them first); the binary and every
// flag drop out. A leftover non-pattern token can only ever fail to match, which
// under-reports rather than false-alarms.
function runnerPatterns(script) {
  if (typeof script !== 'string') return [];
  if (!/(^|\s)--test(\s|$)/.test(script)) return []; // not a glob-driven runner
  return script
    .split(/\s+/)
    .map((t) => t.replace(/^['"]/, '').replace(/['"]$/, ''))
    .filter((t) => t && t !== 'node' && !t.startsWith('-'));
}

const ESCAPE_RE = /[.+^${}()|[\]\\]/g;
const STAR_STAR = '\u0000'; // placeholder for a whole `**` path segment

// A minimal glob → matcher for those patterns, applied per path segment so `**`
// is only special as a segment of its own: `**` spans directories, `*` and `?`
// stay inside one segment. A pattern carrying no wildcard and no file extension
// is a DIRECTORY argument — `node --test <dir>` recurses — so it covers
// everything beneath it.
function toMatcher(pattern) {
  const p = pattern.replace(/\/+$/, '');
  if (!/[*?]/.test(p) && !/\.[a-z0-9]+$/i.test(p)) {
    return (f) => f === p || f.startsWith(`${p}/`);
  }
  const source = p
    .split('/')
    .map((seg) =>
      seg === '**'
        ? STAR_STAR
        : seg.replace(ESCAPE_RE, '\\$&').replace(/\*/g, '[^/]*').replace(/\?/g, '[^/]'),
    )
    .join('/')
    // A leading `**/` matches ZERO or more directories — that's what makes
    // extension-test/**/*.test.js cover extension-test/host-policy.test.js too.
    .split(`${STAR_STAR}/`)
    .join('(?:.*/)?')
    .split(`/${STAR_STAR}`)
    .join('(?:/.*)?')
    .split(STAR_STAR)
    .join('.*');
  const re = new RegExp(`^${source}$`);
  return (f) => re.test(f);
}

const matchers = (patterns) => patterns.map(toMatcher);
const anyMatch = (ms, file) => ms.some((m) => m(file));

export default {
  id,
  severity,
  description: "package.json's test script globs reach every committed test file",
  doc,
  why,

  run(ctx) {
    const raw = ctx.read('package.json');
    if (!raw) return [];
    let scripts;
    try {
      scripts = JSON.parse(raw).scripts || {};
    } catch {
      return []; // malformed package.json breaks npm first — not this check's finding
    }

    const covered = matchers(runnerPatterns(scripts.test));
    if (!covered.length) return []; // no glob-driven `test` script — nothing to enforce
    const exempt = matchers(runnerPatterns(scripts['test:e2e']));

    // ctx.files is the whole repo under the engine's default `all` sweep; a
    // --changed run narrows it, which only ever under-reports.
    return ctx.files
      .filter(isTestFile)
      .filter((f) => !anyMatch(covered, f) && !anyMatch(exempt, f))
      .map((file) => ({
        rule: id,
        severity,
        file,
        line: null,
        what: `${file} is reached by no pattern in package.json's \`test\` script`,
        why,
        fix:
          'add a glob covering it to the `test` script in package.json — or, if it is a heavy ' +
          'CI-only test, to `test:e2e` (which this check reads as the declared carve-out)',
        doc,
      }));
  },
};
=== pipeline-site-agnostic.mjs ===
// gcec local check: the shared extraction pipeline never names a site. The core
// generic extractor, the orchestrator, the registry and the shared helpers —
// everything under extension/event-extractors/ that is NOT custom/ — run on every
// page, so none of them may carry knowledge of one specific site. The rule this
// converts is RULES.md's "Architecture rules of the road": the generic extractor
// is the base layer of every extraction and "may never know about a specific
// site"; custom/ is the one place per-site knowledge lives (guarded from the
// other side by custom-sources-flat).
//
// Why a check and not just prose: a host-gated special case in shared code fails
// SILENTLY in the one place this repo automates a decision. The site it patches
// works, every suite stays green — and the generic-coverage gate then reports
// that site as gap-free, because the gap was hardcoded away rather than closed
// generically. RULES.md reads a no-gap site as "a candidate for deleting the
// per-site source and listing the host in supportedDomains", so the erosion
// doesn't just sit there: it feeds a wrong answer into the next decision, with
// nothing red anywhere. It also quietly ends the property the architecture is
// built to keep — adding a host is a single-file change.
//
// SCOPE, stated honestly: this catches the obvious carrier, a supported host
// named in shipped code. A site-specific hack keyed on something else (a
// selector only one site uses) is not detectable statically and stays the
// reader's job — which is why the architecture bullet in RULES.md stays whole
// beside this check rather than being deleted.
//
// The host list is READ from the repo, never hardcoded: extension/host-lists.json's
// `supportedDomains` is the one declaration of the hosts we claim (RULES.md:
// "Being supported is DECLARED"), so the check follows that list around instead
// of pinning a copy that would drift.
//
// COMMENTS ARE SKIPPED, deliberately. Naming the site where a generic pattern was
// observed is exactly how this codebase documents evidence — generic-extractor.js
// cites stubhub.com for a venue heuristic, derive-timezone.js cites eventer.co.il
// and visit.tel-aviv.gov.il, embedded-events.js cites livenation.de. Those are
// rationale, not site knowledge. Comments are blanked by a small scanner (not a
// regex) that tracks string literals, so a host inside a 'https://…' string is
// still code and still found.
//
// Local-pack check modules are dependency-free on purpose (see
// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
// so they also load under the repo's own `npm test` (pack.test.mjs).
const id = 'pipeline-site-agnostic';
const severity = 'blocking';
const doc = '.claudinite/local/packs/gcec/RULES.md';
const why =
  'the shared pipeline runs on every page — a host-gated special case there makes the ' +
  'generic-coverage gate report that site as gap-free when the gap was only hardcoded ' +
  'away, and every suite stays green while it happens';

const DIR = 'extension/event-extractors/';
const CUSTOM_DIR = `${DIR}custom/`;
const HOST_LIST = 'extension/host-lists.json';

// Blank every comment, keeping the file's exact length and line breaks so line
// numbers stay true. A hand-rolled scanner rather than a regex because `//`
// inside a string ('https://…') is not a comment and must not swallow the rest
// of the line — that is precisely where a host literal would hide.
function blankComments(src) {
  const out = [];
  let i = 0;
  const keep = (ch) => out.push(ch);
  const blank = (ch) => out.push(ch === '\n' ? '\n' : ' ');
  while (i < src.length) {
    const ch = src[i];
    const next = src[i + 1];
    if (ch === '/' && next === '/') {
      while (i < src.length && src[i] !== '\n') blank(src[i++]);
      continue;
    }
    if (ch === '/' && next === '*') {
      blank(src[i++]);
      blank(src[i++]);
      while (i < src.length && !(src[i] === '*' && src[i + 1] === '/')) blank(src[i++]);
      if (i < src.length) {
        blank(src[i++]);
        blank(src[i++]);
      }
      continue;
    }
    if (ch === '"' || ch === "'" || ch === '`') {
      const quote = ch;
      keep(src[i++]);
      while (i < src.length) {
        if (src[i] === '\\') {
          keep(src[i++]);
          if (i < src.length) keep(src[i++]);
          continue;
        }
        if (src[i] === quote) {
          keep(src[i++]);
          break;
        }
        keep(src[i++]);
      }
      continue;
    }
    keep(src[i++]);
  }
  return out.join('');
}

// A host counts only as a whole label run: "notstubhub.com" is not stubhub.com,
// and inside "visit.tel-aviv.gov.il" the shorter "tel-aviv.gov.il" doesn't match
// on its own (the longer entry in the list does, and is reported instead).
const HOST_CHAR = /[A-Za-z0-9.-]/;
function namesHost(line, host) {
  let from = 0;
  for (;;) {
    const at = line.indexOf(host, from);
    if (at === -1) return false;
    const before = at === 0 ? '' : line[at - 1];
    const afterIndex = at + host.length;
    const after = afterIndex >= line.length ? '' : line[afterIndex];
    if (!HOST_CHAR.test(before) && !HOST_CHAR.test(after)) return true;
    from = at + 1;
  }
}

export default {
  id,
  severity,
  description: "the shared extraction pipeline names no supported site — per-site knowledge lives only in custom/",
  doc,
  why,

  run(ctx) {
    const raw = ctx.read(HOST_LIST);
    if (!raw) return [];
    let hosts;
    try {
      hosts = JSON.parse(raw).supportedDomains;
    } catch {
      return []; // a malformed host list breaks the extension's own tests first
    }
    if (!Array.isArray(hosts) || !hosts.length) return [];
    // Longest first, so a finding names visit.tel-aviv.gov.il rather than the
    // shorter entry it contains.
    const ordered = [...hosts].filter((h) => typeof h === 'string' && h).sort((a, b) => b.length - a.length);

    const findings = [];
    // ctx.files is the whole repo under the engine's default `all` sweep; a
    // --changed run narrows it, which only ever under-reports.
    for (const file of ctx.files) {
      if (!file.startsWith(DIR) || file.startsWith(CUSTOM_DIR)) continue;
      if (!file.endsWith('.js')) continue;
      const src = ctx.read(file);
      if (!src) continue;
      const lines = blankComments(src).split('\n');
      lines.forEach((line, index) => {
        const host = ordered.find((h) => namesHost(line, h));
        if (!host) return;
        findings.push({
          rule: id,
          severity,
          file,
          line: index + 1,
          what: `${file} names the supported site ${host} in shipped code`,
          why,
          fix:
            `move the ${host}-specific handling into extension/event-extractors/custom/<site>.js ` +
            '(the one extensibility point), or generalize it so the pipeline reads what the page ' +
            'says about itself with no host in the condition — citing a site in a COMMENT as ' +
            'evidence for a generic rule is fine and is not what this flags',
          doc,
        });
      });
    }
    return findings;
  },
};
=== regen-artifacts-merge-ours.mjs ===
// gcec local check: every artifact `npm run regen` rewrites carries a `merge=ours`
// entry in .gitattributes. The rule this converts is RULES.md's regen bullet —
// the `ours` driver's file set is "kept in sync with `.gitattributes`" — and
// .gitattributes' own header states the mechanism: on a conflicting merge the
// driver keeps one side automatically, you rerun the generator, and there is
// nothing to resolve by hand.
//
// Why a check and not just prose: the set of regen artifacts GROWS ON ITS OWN.
// Requirement kinds are auto-discovered (dev/requirements/shared/kinds.js — "adding
// a kind is a self-contained folder drop"), so a new `image` kind starts committing
// baselines under dev/requirements/<kind>/cases/*.png with nobody editing a list
// anywhere. .gitattributes, meanwhile, names popup/ and icon/ literally. The new
// kind's PNGs are then off the driver, and nothing says so: every suite stays
// green, `npm run regen` keeps working, and the omission only surfaces later as a
// merge conflict on a BINARY file that git cannot 3-way merge at all — the one
// conflict a human genuinely cannot resolve, hit at the worst moment (mid-merge).
// That gap between an auto-discovered producer and a hand-kept list is exactly
// what a static scan is for.
//
// SCOPE, and how it divides with the canon: the canon's basics/generated-merge-driver
// rule already covers files whose name carries `GENERATED` (this repo's
// generic-coverage.baseline.GENERATED.json / generic-coverage.GENERATED.md). It
// matches that marker case-sensitively, so it sees neither this repo's
// lowercase-`.generated.` artifact (load-order.generated.json) nor the snapshot
// PNGs, which carry no marker in their names at all. This check takes exactly that
// remainder — the repo's own regen outputs the canon marker doesn't name — so the
// two never double-report the same file.
//
// Only the "artifact with no entry" direction is checked. A leftover entry for a
// renamed artifact is cosmetic (the renamed file trips this check under its new
// path), and matching globs against a file list would false-positive under a
// --changed run, where that list is narrowed. Under-reporting is the safe error.
//
// Local-pack check modules are dependency-free on purpose (see
// test-offline-list-sync.mjs's header): plain finding objects, no engine imports,
// so they also load under the repo's own `npm test` (pack.test.mjs).
const id = 'regen-artifacts-merge-ours';
const severity = 'blocking';
const doc = '.claudinite/local/packs/gcec/RULES.md';
const why =
  'a regen artifact off the `ours` driver hits a hand-resolved merge conflict — and the UI ' +
  'baselines are binary PNGs git cannot 3-way merge at all';

// A UI-snapshot baseline: dev/requirements/<kind>/cases/<case>.png, for ANY kind,
// because kinds are auto-discovered and a new image kind must not need this check
// edited to be covered.
const CASE_SNAPSHOT = /^dev\/requirements\/[^/]+\/cases\/[^/]+\.png$/;

// A generated artifact named with the lowercase `.generated.` convention. The
// uppercase GENERATED marker is the canon rule's half of the set, excluded here so
// one file never yields two findings.
function isLowercaseGenerated(file) {
  const base = file.split('/').pop();
  return /\.generated\./.test(base) && !base.includes('GENERATED');
}

// .gitattributes patterns are gitignore-style: `*` and `?` do not cross a `/`,
// `**` does, and a pattern containing no `/` matches by basename at any depth.
function globToRe(glob) {
  let out = '';
  for (let i = 0; i < glob.length; i += 1) {
    const ch = glob[i];
    if (ch === '*') {
      if (glob[i + 1] === '*') {
        out += '.*';
        i += 1;
      } else {
        out += '[^/]*';
      }
      continue;
    }
    if (ch === '?') {
      out += '[^/]';
      continue;
    }
    out += ch.replace(/[.+^${}()|[\]\\]/, '\\$&');
  }
  return new RegExp(`^${out}$`);
}

function oursPatterns(text) {
  return (text || '')
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l && !l.startsWith('#') && /\bmerge=ours\b/.test(l))
    .map((l) => l.split(/\s+/)[0].replace(/^\/+/, ''))
    .map((pattern) => ({ pattern, re: globToRe(pattern), byBasename: !pattern.includes('/') }));
}

export default {
  id,
  severity,
  description: 'every `npm run regen` artifact has a merge=ours entry in .gitattributes',
  doc,
  why,

  run(ctx) {
    // allFiles, not files: this rule reasons ABOUT generated artifacts, so it must
    // still see them if the repo ever marks them linguist-generated (which the
    // engine otherwise drops from ctx.files) — the same reason the canon's
    // generated-merge-driver reads allFiles. Falls back to ctx.files for a context
    // that doesn't draw the distinction.
    const all = ctx.allFiles || ctx.files || [];
    const artifacts = all.filter((f) => CASE_SNAPSHOT.test(f) || isLowercaseGenerated(f));
    if (!artifacts.length) return [];

    const patterns = oursPatterns(ctx.read('.gitattributes'));

    return artifacts
      .filter((file) => {
        const base = file.split('/').pop();
        return !patterns.some((p) => (p.byBasename ? p.re.test(base) : p.re.test(file)));
      })
      .map((file) => {
        // Suggest the shape the repo already uses: one line per snapshot DIRECTORY,
        // one line per generated file.
        const suggestion = CASE_SNAPSHOT.test(file)
          ? `${file.slice(0, file.lastIndexOf('/'))}/*.png`
          : file;
        return {
          rule: id,
          severity,
          file,
          line: null,
          what: `${file} is regenerated by \`npm run regen\` but has no merge=ours entry in .gitattributes`,
          why,
          fix: `add \`${suggestion} merge=ours\` to .gitattributes (beside the other regen artifacts), so a conflicting merge auto-resolves and you rerun the generator instead of hand-merging`,
          doc,
        };
      });
  },
};

1	// Red-first fixture tests for the gcec pack's checks, runnable by this repo's own
2	// `npm test` (no imports from the gitignored .claudinite mount — see the check
3	// module's header). Each rule is shown firing on a violating fixture and staying
4	// quiet on a clean one.
5	import test from 'node:test';
6	import assert from 'node:assert/strict';
7	import testOfflineListSync from './test-offline-list-sync.mjs';
8	import customSourcesFlat from './custom-sources-flat.mjs';
