// Drift guard: every per-site extractor's host must be declared in
// host-lists.json's `supportedDomains` — so a source can never exist for a
// host we don't claim as supported (the toolbar icon would stay blue while the
// popup showed the source's events, and the auto-extractor triage would accept a
// "please support this site" request for a site we already cover).
//
// ONE DIRECTION ONLY, on purpose. The reverse — "every listed domain has a
// source" — is deliberately NOT asserted: `supportedDomains` is the declaration
// of what we support, and a site whose pages the core generic extractor already
// reads correctly is supported with no per-site file at all. Requiring a source
// per entry is exactly the duplication this guard used to force.
//
// Each source's matches() is a regex, not a domain literal, so we can't read the
// domain out of it — instead we LOAD the real sources (DOM-free, pure Node vm,
// the same way extension-test/integration/extension-loads.test.js boots them: only
// matches() runs here, and that's a pure host check) and run the matchers
// against the list.
"use strict";

const { test } = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");

const ROOT = path.join(__dirname, "..", "..");
const EXT = path.join(ROOT, "extension"); // the extension root; pipeline paths are relative to it

// Load event-extractors/registry.js + every event-extractors/custom/*.js into a
// bare sandbox.
// No DOM is stubbed: a source's extract() touches document, but only its
// matches() runs here, and that's a pure host regex. registry.js sets
// globalThis.GCal (the context's global), each source pushes its matcher onto
// GCal.sources. Returns the assembled GCal.
function loadSources() {
  const sandbox = { URL };
  vm.createContext(sandbox);
  const run = (rel) => vm.runInContext(fs.readFileSync(path.join(EXT, rel), "utf8"), sandbox, { filename: rel });
  run("event-extractors/registry.js");
  const sources = fs
    .readdirSync(path.join(EXT, "event-extractors/custom"))
    .filter((f) => f.endsWith(".js"))
    .sort();
  for (const f of sources) run(`event-extractors/custom/${f}`);
  return sandbox.GCal;
}

const GCal = loadSources();
const { supportedDomains } = JSON.parse(
  fs.readFileSync(path.join(EXT, "host-lists.json"), "utf8")
);

test("supportedDomains is a non-empty array", () => {
  assert.ok(
    Array.isArray(supportedDomains) && supportedDomains.length > 0,
    "extension/host-lists.json must define a non-empty supportedDomains array"
  );
});

test("every source is represented by a supportedDomains entry (none missing)", () => {

// Regression test for issue #48: the pipeline files must not clobber each
// other's contributions to globalThis.GCal regardless of the order they run in.
// registry.js creates GCal.sources, the helpers add the shared toolbox, and the
// sources push their { name, matches, extract } onto GCal.sources; because every
// file augments GCal with Object.assign (rather than replacing it), loading them
// in any order keeps every contribution intact.
"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const path = require("node:path");
const vm = require("node:vm");

const ROOT = path.join(__dirname, "..", "..");
const EXT = path.join(ROOT, "extension"); // the extension root; pipeline paths are relative to it

function runInFreshSandbox(files) {
  const sandbox = { document: undefined, URL };
  vm.createContext(sandbox);
  for (const file of files) {
    vm.runInContext(fs.readFileSync(path.join(EXT, file), "utf8"), sandbox);
  }
  return sandbox;
}

test("a helper loaded before the registry still leaves both intact", () => {
  // Deliberately load a helper before registry.js (the reverse of the load order).
  const sandbox = runInFreshSandbox(["event-extractors/helpers/dom.js", "event-extractors/registry.js"]);

  // registry.js must not have wiped out the helper's contribution...
  assert.equal(typeof sandbox.GCal.clean, "function", "the dom helper survives");
  // ...nor should the helper have prevented registry.js's bootstrap.
  assert.ok(Array.isArray(sandbox.GCal.sources), "GCal.sources is present");
});

test("a source registers onto GCal.sources whichever order the base files run", () => {
  for (const baseOrder of [
    ["event-extractors/registry.js", "event-extractors/helpers/dom.js"],
    ["event-extractors/helpers/dom.js", "event-extractors/registry.js"],
  ]) {
    const sandbox = runInFreshSandbox(baseOrder);
    assert.doesNotThrow(() => {
      vm.runInContext(
        fs.readFileSync(path.join(EXT, "event-extractors/custom/meetup.js"), "utf8"),
        sandbox
      );
    }, `meetup.js threw with base order ${baseOrder.join(", ")}`);
    const meetup = sandbox.GCal.sources.find((s) => s.name === "meetup");
    assert.ok(meetup, "meetup registered itself onto GCal.sources");
    assert.ok(meetup.matches("www.meetup.com"), "meetup.matches works");
  }
});
